using StateLandGovernance.GovernanceIntelligence.Application.DTOs;
using StateLandGovernance.GovernanceIntelligence.Application.RegulatoryReports;
using StateLandGovernance.GovernanceIntelligence.Application.OfficerFlows;
namespace StateLandGovernance.UnitTests.GovernanceIntelligence;
public sealed class FindingClosureTests
{
 static ComplianceFindingDto Finding(string status="InsufficientInformation")=>new("ANY-RULE","arbitrary-version","AnyCategory","Applicable",status,"High",true,true,"Original input","External approval required","Missing","MissingInputs","Authority","Document","Section","Obtain independent review");
 static RecordRegulatoryFollowup Input()=>new(Guid.NewGuid(),"ANY-RULE",FindingClosurePolicy.Operation,null,null);
 static RegulatoryFollowupEvent Event(ComplianceFindingDto f)=>new(Guid.NewGuid(),Guid.NewGuid(),f.RuleCode,f.RuleVersion,Guid.NewGuid(),DateTimeOffset.UtcNow,FindingClosurePolicy.Operation,null,null,"",[],"Recorded",1,null,"hash");
 [Theory][InlineData("InsufficientInformation")][InlineData("RequiresHumanReview")]
 public void EveryRequestedStatusAcceptsDirectDisposition(string status){var f=Finding(status);var before=RegulatoryFollowupInput.FindingHash(f);var input=RegulatoryFollowupInput.Validate(Input());Assert.Equal("",input.Remarks);Assert.Empty(input.References!);RegulatoryFollowupInput.ValidateFinding(input,f);var eligibility=FindingClosurePolicy.Evaluate(f,[]);Assert.True(eligibility.CanClose);Assert.False(eligibility.EvidenceRequired);Assert.True(eligibility.ReleasesProgressionHold);Assert.Equal(before,RegulatoryFollowupInput.FindingHash(f));}
 [Theory][InlineData("Compliant")][InlineData("NotApplicable")][InlineData("Conditional")][InlineData("Unknown")]
 public void OtherStatusesDoNotAcceptClosure(string status)=>Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.ValidateFinding(Input(),Finding(status)));
 [Fact] public void EmptyOrOmittedRemarksAndReferencesAreNotFabricated(){foreach(var x in new[]{Input(),Input() with{Remarks="",References=[]}}){var normalized=RegulatoryFollowupInput.Validate(x);Assert.Equal("",normalized.Remarks);Assert.Empty(normalized.References!);}Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.Validate(Input() with{Remarks=new string('x',2001)}));Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.Validate(Input() with{ReviewOutcome="NoAdditionalConcern"}));}
 [Fact] public void ExistingActionsStillRequireRemarksAndReviewPayload(){Assert.Throws<ArgumentException>(()=>RegulatoryFollowupInput.Validate(Input() with{Operation="HumanReviewRecorded",ReviewOutcome="NoAdditionalConcern",References=[]}));}
 [Fact] public void ClosureResolvesC4WithoutCreatingExternalApproval(){var f=Finding();var closed=Event(f);Assert.True(FindingClosurePolicy.Evaluate(f,[]).CanClose);Assert.True(FindingClosurePolicy.CanResolveC4Finding(f));Assert.Empty(RegulatoryProgression.Holds([f],[closed]));Assert.False(FindingClosurePolicy.Evaluate(f,[closed]).CanClose);}
 [Fact] public void ClosureOfOneFindingLeavesOtherObligationsUnchanged(){var f=Finding();var other=f with{RuleCode="OTHER"};var holds=RegulatoryProgression.Holds([f,other],[Event(f)]);Assert.Single(holds);Assert.Contains(holds,x=>x.Contains("OTHER"));}
 [Fact] public void KnownLocalDsReviewCanReleaseOnlyItsOwnHold(){var f=Finding() with{RuleCode="NPD-LOC-001",RuleVersion="1.0",Category="Completeness",IsBlocking=false,SourceAuthority="Department of National Planning",SourceDocument="Operational Manual / Project Submission Format (January 2019)",SourceSection="Item 3 — Project Location",ExpectedRequirement="Full project location hierarchy (Province, District, DSD, GND) must be specified."};Assert.Empty(RegulatoryProgression.Holds([f],[Event(f)]));var external=Event(f) with{Operation="HumanReviewRecorded",ReviewOutcome="FurtherInstitutionalLegalReview",Revision=0};Assert.Empty(RegulatoryProgression.Holds([f],[external,Event(f)]));}
 [Fact] public void MigrationDownRetainsDirectDispositionHistory()=>Assert.Throws<InvalidOperationException>(()=>new StateLandGovernance.GovernanceIntelligence.Infrastructure.Persistence.Migrations.AllowDirectOfficerDisposition().DownOperations);
}
